SELECT w.execution_reason, CASE WHEN w.execution_message LIKE '%BALANCED_NEUTRAL_5M_WATCH_1H%' THEN 'FIX11G' WHEN w.execution_message LIKE '%BALANCED_NEUTRAL_5M:%' THEN 'FIX112B' WHEN w.execution_message LIKE '%approved 100\%%' THEN 'BALANCED_FULL' WHEN w.execution_message LIKE '%approved 75\%%' OR w.execution_message LIKE '%BALANCED_STRONG%' THEN 'BALANCED_STRONG' WHEN w.execution_message LIKE '%approved 50\%%' OR w.execution_message LIKE '%BALANCED_EARLY%' THEN 'BALANCED_EARLY' ELSE 'OTHER' END AS htf_code, COUNT(*) AS n, SUM(p.realized_pnl > 0) AS wins, SUM(p.realized_pnl < 0) AS losses, SUM(p.status = 'STOPPED') AS stopped, ROUND(SUM(p.realized_pnl), 4) AS pnl, ROUND(SUM(p.entry_price * p.quantity), 2) AS notional FROM crypto_ai.wallet_trade w JOIN crypto_ai.paper_position p ON p.signal_id = w.signal_id WHERE w.side = 'BUY' AND p.status IN ('CLOSED','STOPPED') GROUP BY w.execution_reason, htf_code ORDER BY w.execution_reason, htf_code LIMIT 60;